using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AlchemicalRevelationCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/AlchemicalRevelationCustomDescription", order = 0)]
public class AlchemicalRevelationCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private BattleActionWithMinimumAstriumActionCustomDescription battleActionWithMinimumAstriumActionCustomDescription;

	[SerializeField]
	private DrawAction defaultDrawAction;

	private AstriumEffect astriumEffect => battleActionWithMinimumAstriumActionCustomDescription.PlayerEffectsList.AstriumEffect;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		defaultDrawAction.GetActionDescription(-1).RemoveLast();
		DrawAction drawAction = battleAction as DrawAction;
		string localizedThenDecreaseEffect = base.localizationManager.GetLocalizedThenDecreaseEffect(astriumEffect, drawAction.DecreaseEffectAmount);
		return Smart.Format(GetRawLocalizedDescription(battleAction), drawAction.DrawAmountBasedOnEffectDivider, localizedThenDecreaseEffect);
	}
}
